testbench_sv:
`timescale 1ns/1ps
module tb;
  reg  [7:0] a, b;
  wire [7:0] y;

  bitwise_xor8 dut (.a(a), .b(b), .y(y));

  initial begin
    #10000 $display("##TIMEOUT");
    $finish;
  end

  initial begin
    a = 8'h00; b = 8'h00; #1;
    if (y === 8'h00) $display("##TEST T1 PASS exp=00 got=%02h", y);
    else $display("##TEST T1 FAIL exp=00 got=%02h", y);

    a = 8'hA5; b = 8'h00; #1;
    if (y === 8'hA5) $display("##TEST T2 PASS exp=a5 got=%02h", y);
    else $display("##TEST T2 FAIL exp=a5 got=%02h", y);

    a = 8'h5A; b = 8'h5A; #1;
    if (y === 8'h00) $display("##TEST T3 PASS exp=00 got=%02h", y);
    else $display("##TEST T3 FAIL exp=00 got=%02h", y);

    a = 8'hAA; b = 8'h55; #1;
    if (y === 8'hFF) $display("##TEST T4 PASS exp=ff got=%02h", y);
    else $display("##TEST T4 FAIL exp=ff got=%02h", y);

    a = 8'h3C; b = 8'hA7; #1;
    if (y === 8'h9B) $display("##TEST T5 PASS exp=9b got=%02h", y);
    else $display("##TEST T5 FAIL exp=9b got=%02h", y);

    a = 8'h01; b = 8'h00; #1;
    if (y === 8'h01) $display("##TEST T6 PASS exp=01 got=%02h", y);
    else $display("##TEST T6 FAIL exp=01 got=%02h", y);

    b = 8'hFF; #1;
    if (y === 8'hFE) $display("##TEST T7 PASS exp=fe got=%02h", y);
    else $display("##TEST T7 FAIL exp=fe got=%02h", y);

    $display("##DONE");
    $finish;
  end
endmodule

reference_sv:
module bitwise_xor8 (
    input  logic [7:0] a,
    input  logic [7:0] b,
    output logic [7:0] y
);
    assign y = a ^ b;
endmodule
